Reference implementation (Python 3.12+):
```python
from collections import deque

def is_bipartite(graph):
    color = {}
    for start in graph:
        if start in color: continue
        color[start] = 0; q = deque([start])
        while q:
            v = q.popleft()
            for u in graph[v]:
                if u not in color: color[u] = 1 - color[v]; q.append(u)
                elif color[u] == color[v]: return False
    return True

assert is_bipartite({0:[1,3],1:[0,2],2:[1,3],3:[0,2]})
assert not is_bipartite({0:[1,2],1:[0,2],2:[0,1]})
```

